import {ProfileBook,playTime} from './profiles.js';
import {mapShapeLabel} from './world-geometry.js';
import {COMBAT_SPEED,upgradeName} from './balance.js';
import {RITUALS} from './encounters.js';
import {CHARACTERS,ACHIEVEMENTS,character,metaText,buyCharacter,selectCharacter,achievementProgress,claimAchievement,achievementReward,achievementClaimed,readyAchievements} from './progression.js';
import {bindMovementInput} from './movement-input.js';
import {skillText,prerequisitesMet} from './skill-tree.js';
import {VERSION,BASES,ARTIFACTS,RECIPES,ULTIMATES,MAPS,BRANCHES,SKILLS,RANKS,RANK_NAMES,RANK_COLORS,weapon,artifact,artifactValue} from './catalog.js';
import {freshSave,validateSave,validateRun,newRun,newCharacterRun,step,points,learnSkill,forge,forgeCost,evolve,fuse,knownBadge,makeChoices,takeChoice,claimRun,earnedGold,buyRevive,reviveCost,reviveWallet,finishDeath,bonuses,weaponStats,recordDiscoveries,capacity,heroXpForLevel,rerollChoices,acknowledgeChest} from './core.js';
import {weaponIcon} from './weapon-art.js';
import {artifactIcon} from './artifact-art.js';
import {collectedBases,mapUnlocked} from './core.js';
import {CHANGELOG,currentChanges,unreadChanges} from './changelog.js';
import {SaveStore,decodeSave} from './storage.js';import {Score} from './audio.js';
import {translate} from './i18n.js';import {Renderer} from './render.js';import {Updates} from './updates.js';
const $=id=>document.getElementById(id), panel=$('panel'),body=$('panel-body');let save=freshSave(),run=null,playing=false,paused=false,screen='',selectedMap='village',last=0,hudClock=0,saveClock=0,noticeTimer,toastTimer,input={x:0,y:0},keys=new Set(),pointer=null,atGate=true,selectedBranch='vitality',selectedSkill='vitality_tender_flame',killSoundAt=0,killSoundIndex=0;
const saves=new SaveStore(localStorage),loaded=saves.load();save=loaded.profile;run=loaded.run;const profileBook=new ProfileBook(localStorage,saves,loaded);let loadError=loaded.status==='blocked'||profileBook.blocked;if(run?.over&&!run.awaitingRevive)claimRun(run,save);
const t=k=>translate(save.settings.language,k),fmt=s=>`${Math.floor(s/60).toString().padStart(2,'0')}:${Math.floor(s%60).toString().padStart(2,'0')}`;
const rankBadge=(rank,compact=false)=>`<span class="rank-badge rank-${rank}" style="--rank-color:${RANK_COLORS[rank]}">${RANKS[rank]}${compact?'':' · '+t(RANK_NAMES[rank])}</span>`;
const renderer=new Renderer($('world'));const music=new Score();let audioReady=false,nativeBackground=false;const sounds={};
function sound(id){if(!audioReady||!save.settings.sfx)return;if(save.settings.soundQuality==='low'&&id==='ritual')return;let a=sounds[id];if(!a)a=sounds[id]=new Audio(`./assets/${id}.wav`);a.volume=save.settings.sfx;a.currentTime=0;a.play().catch(()=>{});}
function unlockAudio(){audioReady=true;syncAudio();music.unlock();}
function syncAudio(){music.sync({enabled:audioReady&&!save.settings.musicMuted&&!document.hidden&&!nativeBackground,volume:save.settings.music*(playing?(paused?.45:1):.55),mapId:run?.mapId,scene:atGate?'intro':playing&&!run?.over?'journey':'menu',boss:playing&&run?.enemies.some(e=>e.boss&&e.hp>0)});}
function persist(checkpoint=false){if(loadError)return false;try{if(run)recordDiscoveries(run,save);profileBook.save(save,run);return saves.write(save,run,{checkpoint:checkpoint===true});}catch(e){notice(e.message.includes('another tab')?'Progress changed in another tab. Reload this tab.':'Progress could not be saved. Export a backup.');return false;}}

function notice(msg){$('notice').textContent=t(msg);$('notice').style.display='block';clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>$('notice').style.display='none',4200);}
function toast(msg){$('toast').textContent=t(msg);clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').textContent='',3000);}
function nativeRun(){if(globalThis.WispboundNative)WispboundNative.setRunActive(!!run&&!run.over);}
const updater=new Updates({notify:()=>{if(screen==='updates')updatesPanel();else if(screen==='install')install();},getRun:()=>run,save:()=>persist(true)});
function show(name,title,html,close=true){if(name!=='skills'&&$('skill-popup').open)$('skill-popup').close();releasePointer();panel.dataset.screen=name;screen=name;if(playing){paused=true;input={x:0,y:0};keys.clear();syncAudio();}body.innerHTML=`<div class="panel-heading"><h2>${t(title)}</h2>${close?`<button class="close" data-action="close" aria-label="${t('Close')}">×</button>`:''}</div>${html}`;if(!panel.open)panel.showModal();}
function closePanel(){if(screen==='level'||screen==='result'||screen==='fallen'||screen==='chest')return;const previous=screen;if(screen==='whatsnew'){const old=save.lastSeenBuild;save.lastSeenBuild=Math.max(Number.isSafeInteger(old)?old:0,VERSION.build);if(!persist()){if(old===undefined)delete save.lastSeenBuild;else save.lastSeenBuild=old;}}panel.close();screen='';if(previous==='install'&&!loadError&&unreadChanges(save).length){whatsNew(true);return;}if(playing){paused=false;syncAudio();}else if(!atGate)home();}
panel.addEventListener('cancel',e=>{e.preventDefault();closePanel();});
function titleScreen(){persist();releasePointer();atGate=true;playing=false;paused=false;screen='';if(panel.open)panel.close();$('home').hidden=true;$('game').hidden=true;$('gate').hidden=false;$('gate').innerHTML=`<div class="gate-art"></div><div class="gate-mist"></div><div class="gate-sparks" aria-hidden="true">${Array.from({length:14},(_,i)=>`<i style="--i:${i};--top:${20+i%5*12}%"></i>`).join('')}</div><div class="gate-content"><div class="eyebrow">${t('A flame between worlds')}</div><img src="assets/icon.svg" class="gate-emblem" alt=""><h1>WISPBOUND</h1><p>${t('The forest remembers your name.')}</p><nav class="title-actions"><button class="gate-enter" data-action="entercamp" ${loadError?'disabled':''}>${t('Continue')}</button><button data-action="newprofile" ${loadError?'disabled':''}>${t('New game')}</button><button data-action="loadprofiles" ${loadError?'disabled':''}>${t('Load')} · ${profileBook.book.slots.length}</button><button data-action="settings">${t('Settings')}</button></nav><small>${character(save.selectedCharacter).name} · ${t('Hero level')} ${save.heroLevel} · ${save.playTimeEstimated?'≥ ':''}${playTime(save.playedSeconds)}</small></div><div class="gate-version">V${VERSION.name} · ${t('Carry the last light.')}</div>`;syncAudio();}
function enterCamp(){if(loadError)return;home();if(unreadChanges(save).length)whatsNew(true);}
function activateProfile(data){save=data.profile;run=data.run;selectedMap=run?.mapId||'village';inventorySignature='';nativeRun();syncAudio();enterCamp();}
function newProfile(){if(!persist(true))return;try{activateProfile(profileBook.create(save,run));}catch(e){notice(e.message.includes('another tab')?e.message:'Progress could not be saved. Export a backup.');}}
function loadProfiles(){if(!persist(true))return;show('profiles','Load',`<p>${t('Each hero keeps separate progress. New game keeps your previous heroes.')}</p><div class="save-slots">${profileBook.list().map(slot=>{const p=slot.profile,c=character(slot.run?.characterId||p.selectedCharacter),active=p.slotId===save.slotId;return `<article class="save-slot ${active?'selected':''}"><img src="assets/characters/${c.id}.svg" alt="${c.name}"><div><h3>${c.name} · ${t('Hero level')} ${p.heroLevel}</h3><b>${p.playTimeEstimated?'≥ ':''}${playTime(p.playedSeconds)}</b><small>${Math.floor(p.gold)} ${t('Gold')} · ${p.shards} ${t('Shards')}</small><small>${slot.run&&!slot.run.over?slot.run.mapId+' · '+fmt(slot.run.time):t('Camp')} · ${new Date(slot.createdAt).toLocaleDateString(save.settings.language)}</small></div><button data-slot="${slot.id}">${t(active?'Continue':'Load')}</button></article>`;}).join('')}</div><p class="muted">${t('Older heroes show the minimum known time; new play time is recorded exactly.')}</p>`);}
function toggleMusic(){if(profileAction(p=>{p.settings.musicMuted=!p.settings.musicMuted;return true;})){if(!save.settings.musicMuted)music.unlock();syncAudio();settings();}}
function killSound(){const now=performance.now(),gap=save.settings.soundQuality==='low'?220:130;if(now<killSoundAt)return;killSoundAt=now+gap;sound('kill-'+(killSoundIndex++%3+1));}
function home(){releasePointer();atGate=false;$('gate').hidden=true;playing=false;paused=false;syncAudio();$('home').hidden=false;$('game').hidden=true;if(panel.open)panel.close();screen='';document.documentElement.lang=save.settings.language;nativeRun();$('home').innerHTML=`<div class="home-wrap"><header class="brandbar"><span><img class="brandmark" src="assets/icon.svg" alt="">WISPBOUND</span><div class="camp-corner"><button class="achievement-shortcut" data-action="achievements">${t('Achievements')} <b>${readyAchievements(save).length?'+'+readyAchievements(save).length:save.achievementClaims.length+'/'+ACHIEVEMENTS.length}</b></button><small>V${VERSION.name}${VERSION.test?' TEST':''}</small></div></header><div class="hero-grid"><div class="hero-copy"><div class="eyebrow">${t('Carry the last light.')}</div><h1>WISPBOUND</h1><p>${t('A lantern. A lost village. A thousand restless spirits. Walk your own path through the dark.')}</p><div class="row"><button class="primary" data-action="${run&&(!run.over||run.awaitingRevive)?'continue':'journey'}">${t(run&&(!run.over||run.awaitingRevive)?'Continue journey':'Begin journey')} &nbsp; ↗</button>${run&&(!run.over||run.awaitingRevive)?`<button class="quiet" data-action="end">${t('End journey')}</button>`:''}</div><div class="hero-stats"><div><b>${save.heroLevel}</b><span>${t('Hero level')}</span></div><div><b>${Math.floor(save.gold)}</b><span>${t('Gold')}</span></div><div><b>${save.discovered.length}<small> / 26</small></b><span>${t('Discoveries')}</span></div></div></div><div class="art-wrap"><img class="hero-art" src="assets/cover.svg" alt="WISPBOUND pixel art: a wanderer approaching the last light in a forest chapel"><div class="art-caption">${t('Carry the last light.')} &nbsp; · &nbsp; ${t('Walk a loop to seal a ritual')}</div></div></div><nav class="nav-cards"><button data-action="characters"><b>${t('Characters')}</b><span>${character(save.selectedCharacter).name} · ${save.characters.length}/12</span></button><button data-action="arsenal"><b>${t('The Arsenal')}</b><span>${t('12 weapons · 24 paths')}</span></button><button data-action="skills"><b>${t('Skill tree')}</b><span>${t('54 skills · 6 final masteries')}</span></button><button data-action="codex"><b>${t('The Codex')}</b><span>${t('Discover the hidden rituals')}</span></button><button data-action="settings"><b>${t('Settings')}</b><span>${t('Controls, sound & updates')}</span></button></nav><footer><span>${t('No account required. Progress is saved on this device.')}</span><div class="row"><button class="text-link" data-action="install">${t('Install & download')}</button><button class="text-link" data-action="privacy">${t('Privacy')}</button><button class="text-link" data-action="title">${t('Title screen')}</button></div></footer></div>`;}
function journey(){if(!mapUnlocked(save,selectedMap))selectedMap='village';const c=character(save.selectedCharacter);show('journey','Choose your journey',`<div class="selected-character"><img src="assets/characters/${c.id}.svg" alt="${c.name}"><div><h3>${c.name}</h3><small>${t('Starting weapon')}: ${weapon(c.weapon).name}</small></div>${weaponIcon(c.weapon)}<button data-action="characters">${t('Change character')}</button></div><div class="cards maps">${MAPS.map((m,i)=>{const unlocked=mapUnlocked(save,m.id);return `<button class="card map-card ${selectedMap===m.id?'selected':''} ${unlocked?'':'locked-map'}" data-map="${m.id}" ${unlocked?'':'disabled'}><span class="map-number">0${i+1}</span><h3>${unlocked?m.name:'???'}</h3>${unlocked?`<small>${m.duration/60} ${t('minutes')} ${save.clearedMaps.includes(m.id)?'· ✓ '+t('Completed'):''}</small><small class="map-shape">${t(mapShapeLabel(m.id))}</small><small>${t(m.story)}</small>`:`<small>${t('Clear the previous journey to reveal this map.')}</small>`}</button>`;}).join('')}</div><div class="actionbar"><button class="primary" data-action="start">${t('Begin journey')} ↗</button></div>`);}
function profileAction(action){const previous=structuredClone(save);if(!action(save))return false;if(persist())return true;save=previous;return false;}
function characters(){show('characters','Characters',`<div class="row between"><p>${t('Each character begins with their own weapon. Buy once with earned gold.')}</p><b class="gold">${Math.floor(save.gold)} ${t('Gold')}</b></div><div class="character-grid">${CHARACTERS.map(c=>{const owned=save.characters.includes(c.id),active=save.selectedCharacter===c.id;return `<article class="character-card ${owned?'owned':'locked'} ${active?'selected':''}" style="--character:${c.color}"><div class="portrait-wrap"><img src="assets/characters/${c.id}.svg" alt="${c.name}" loading="lazy"><span>${owned?t(active?'Selected':'Owned'):c.price+' '+t('Gold')}</span></div><div class="character-info"><h3>${c.name}</h3><small>${metaText(c,'title',save.settings.language)}</small><div class="character-weapon">${weaponIcon(c.weapon)}<span>${weapon(c.weapon).name}<small>${t(kindName(weapon(c.weapon).kind))}</small></span></div><p>${t(weapon(c.weapon).description)}</p><div class="character-ritual"><b>${t(RITUALS[c.id].name)}</b><small>${t(RITUALS[c.id].description)}</small><small>${t('When charged, walk a closed loop to invoke your ritual.')}</small></div><button class="${owned?'quiet':'primary'}" ${active||!owned&&save.gold<c.price?'disabled':''} ${owned?`data-character="${c.id}"`:`data-buycharacter="${c.id}"`}>${t(active?'Selected':owned?'Select character':'Unlock character')}${owned?'':' · '+c.price}</button></div></article>`;}).join('')}</div><div class="actionbar"><button data-action="journey">${t('Choose your journey')} ↗</button></div>`);}
function achievements(){const ready=readyAchievements(save);show('achievements','Achievements',`<div class="achievement-summary"><div><b>${save.achievementClaims.length} / ${ACHIEVEMENTS.length}</b><span>${t('Rewards claimed')}</span></div><div class="gold">${Math.floor(save.gold)} ${t('Gold')}</div><button class="primary" data-action="claimall" ${ready.length?'':'disabled'}>${t('Claim available')} · ${ready.length}</button></div><p class="panel-note">${t('Each reward can be claimed once. Journey statistics count when a journey ends.')}</p><div class="achievement-list">${[...ACHIEVEMENTS].sort((a,b)=>Number(ready.includes(b))-Number(ready.includes(a))||Number(save.achievementClaims.includes(a.id))-Number(save.achievementClaims.includes(b.id))).map(a=>{const value=achievementProgress(save,a),claimed=achievementClaimed(save,a.id),reward=achievementReward(a),complete=save.achievementClaims.includes(a.id)||value>=a.target;return `<article class="achievement-row ${claimed?'claimed':complete?'complete':''}"><span class="achievement-medal">${claimed?'✓':complete?'✦':'◇'}</span><div><h3>${metaText(a,'name',save.settings.language)}</h3><p>${metaText(a,'description',save.settings.language)}</p><div class="meter"><i style="width:${value/a.target*100}%"></i></div><small>${value} / ${a.target}</small></div><button data-achievement="${a.id}" ${complete&&!claimed?'':'disabled'}><b>${claimed?t('Claimed'):(save.achievementClaims.includes(a.id)?'':reward.gold+' '+t('Gold')+' · ')+reward.shards+' '+t('Shards')+(reward.character?' · '+character(reward.character).name:'')}</b><small>${claimed?'✓':t(complete?'Claim reward':'In progress')}</small></button></article>`;}).join('')}</div>`);}

const kindName=k=>({pulse:'Shockwave pulses',bolt:'Homing needles',trail:'Burning trails',puddle:'Alchemical pools',bird:'Seeking ravens',tether:'Cutting threads',orbit:'Orbiting blades',meteor:'Falling meteors',boomerang:'Returning sickles',cone:'Flame fans',mine:'Explosive wards',lightning:'Chain lightning',sanctuary:'Healing sanctuary',solar:'Solar barrage'}[k]||k);
const unitName=k=>({pulse:'Pulses',bolt:'Projectiles',trail:'Trails',puddle:'Pools',bird:'Ravens',tether:'Targets',orbit:'Blades',meteor:'Meteors',boomerang:'Sickles',cone:'Flames',mine:'Wards',lightning:'Targets'}[k]||'Shots / targets');
function arsenal(){show('arsenal','The Arsenal',`<div class="rank-legend">${RANKS.map((_,i)=>rankBadge(i)).join('')}</div><p>${t('Forging is permanent. Evolutions are discovered during each journey.')}</p><p class="panel-note">${t('Collected weapons')} · ${save.collectedWeapons.length}/12 — ${t('Find new weapons during a journey to add them to your Arsenal.')}</p><p class="gold">${t('Gold')}: ${Math.floor(save.gold)} &nbsp; · &nbsp; ${t('Shards')}: ${save.shards}</p><div class="cards">${collectedBases(save).map(w=>{const rank=save.ranks[w.id]||0,cost=forgeCost(rank);return `<div class="card">${weaponIcon(w.id,'',w.rank??save.ranks[w.id]??0)}${rankBadge(rank)}<h3>${w.name}</h3><small class="weapon-type">${t(kindName(w.kind))}</small><p>${t(w.description)}</p><small>+${Math.round(rank*6.5)}% ${t('damage')}</small><button style="margin-top:14px" data-forge="${w.id}" ${rank===7||save.gold<cost.gold||save.shards<cost.shards?'disabled':''}>${t(rank===7?'Max rank':'Forge')}${rank<7?` → ${rankBadge(rank+1)}<small>${cost.gold} ${t('Gold')} · ${cost.shards} ${t('Shards')}</small>`:''}</button></div>`;}).join('')}</div>`);}
function skills(){
 const language=save.settings.language,branch=BRANCHES.find(b=>b.id===selectedBranch),nodes=SKILLS.filter(n=>n.branch===branch.id);if(!nodes.some(n=>n.id===selectedSkill))selectedSkill=nodes[0].id;const chosen=nodes.find(n=>n.id===selectedSkill),spent=save.skills.reduce((v,id)=>v+(SKILLS.find(n=>n.id===id)?.cost||0),0),positions=[[50,6],[20,23],[80,23],[20,41],[80,41],[50,58],[20,75],[80,75],[50,94]];
 const nodeState=n=>save.skills.includes(n.id)?'learned':prerequisitesMet(save,n)?'available':'locked';
 const edges=nodes.flatMap((n,i)=>[...n.requires,...n.anyRequires].map(id=>{const j=nodes.findIndex(p=>p.id===id),[x1,y1]=positions[j],[x2,y2]=positions[i];return `<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" class="${save.skills.includes(id)?'lit':''}"/>`;})).join('');
 show('skills','Skill tree',`<div class="tree-heading"><div><div class="eyebrow">${t('The Constellation')}</div><p>${t('Tap any skill to see its effect and unlock it.')}</p></div><div class="tree-budget"><b>${points(save)}</b><span>${t('Skill points')}</span><small>${spent} ${t('Spent')} · ${save.skills.length}/${SKILLS.length}</small></div></div>${save.refundedSkills?`<p class="panel-note">${t('Your old skill points have been refunded. Build a new path.')}</p>`:''}<nav class="tree-branches" aria-label="${t('Skill branches')}">${BRANCHES.map(b=>`<button data-branch="${b.id}" class="${b.id===branch.id?'active':''}" style="--branch:${b.color}">${skillText(b,'name',language)}<small>${save.skills.filter(id=>SKILLS.find(n=>n.id===id)?.branch===b.id).length}/9</small></button>`).join('')}</nav><div class="tree-layout" style="--branch:${branch.color}"><div class="constellation"><svg viewBox="0 0 100 100" preserveAspectRatio="none" aria-hidden="true">${edges}</svg>${nodes.map((n,i)=>`<button class="constellation-node ${nodeState(n)} ${n.keystone?'keystone':''} ${n.capstone?'capstone':''} ${selectedSkill===n.id?'selected':''}" style="left:${positions[i][0]}%;top:${positions[i][1]}%" data-node="${n.id}" aria-pressed="${selectedSkill===n.id}"><span class="node-orb">${save.skills.includes(n.id)?'✓':n.keystone?'✧':i+1}</span><b>${skillText(n,'name',language)}</b><small>${n.cost} ${t('points')}</small></button>`).join('')}</div></div><div class="tree-footer"><small>${t('54 skills. 54 points. Learn all eight skills in a branch to unlock its final mastery.')}</small><button data-action="respec">${t('Reset skills')}</button></div>`);
}

function skillPopup(id){const n=SKILLS.find(n=>n.id===id);if(!n)return;selectedSkill=id;const b=BRANCHES.find(b=>b.id===n.branch),lang=save.settings.language,owned=save.skills.includes(id),eligible=prerequisitesMet(save,n),dlg=$('skill-popup');dlg.style.setProperty('--branch',b.color);dlg.innerHTML=`<div class="panel-heading"><span class="eyebrow">${skillText(b,'name',lang)} · ${t(n.capstone?'Final mastery':n.keystone?'Keystone':'Talent')}</span><button class="close" data-action="closeskill" aria-label="${t('Close skill')}">×</button></div><div class="skill-detail"><h3 id="skill-title">${skillText(n,'name',lang)}</h3><p>${skillText(n,'description',lang)}</p><div class="skill-path">${t('Requires')}: ${n.requires.length?n.requires.map(id=>skillText(SKILLS.find(x=>x.id===id),'name',lang)).join(' + '):n.anyRequires.length?n.anyRequires.map(id=>skillText(SKILLS.find(x=>x.id===id),'name',lang)).join(' '+t('or')+' '):t('No prerequisite')}</div><div class="skill-balance">${points(save)} ${t('Skill points')}</div><button class="primary" data-skill="${id}" ${owned||!eligible||points(save)<1?'disabled':''}>${t(owned?'Learned':'Learn')} ${owned?'✓':'· 1 '+t('points')}</button><small>${t('Skills take effect on your next journey.')}</small></div>`;if(!dlg.open)dlg.showModal();}

function codex(){show('codex','The Codex',`<p>${t('One branch per weapon, per journey. An Ultimate uses one weapon slot.')}</p><p class="gold">${save.discovered.length} / 26 ${t('Discovered')}</p><div class="cards">${collectedBases(save).map(w=>`<div class="card">${weaponIcon(w.id,'',w.rank??save.ranks[w.id]??0)}<h3>${w.name}</h3>${RECIPES.filter(r=>r.baseId===w.id).map(r=>save.discovered.includes(r.id)?`<div class="recipe-line"><b class="gold">${r.name}</b><br>${w.name} Lv.7 + ${artifactIcon(r.artifactId,'inline-art')} ${artifact(r.artifactId).name} Lv.6 + ${t('Elite chest')}<br><span class="muted">${t(r.description)}</span></div>`:`<div class="recipe-line unknown">? &nbsp; ${t('Unknown ritual')}</div>`).join('')}</div>`).join('')}</div><div class="section-label">${t('Ultimate rituals')}</div><div class="cards">${ULTIMATES.map(u=>`<div class="card">${save.discovered.includes(u.id)?`${weaponIcon(u.id)}<h3>${u.name}</h3><small>${u.components.map(id=>weapon(id).name).join(' + ')} + ${t('Catalyst')}</small><p>${t(u.description)}</p>`:`<h3 class="unknown">? &nbsp; ${t('Unknown ritual')}</h3><p>${t('Perform an evolution to reveal its recipe here.')}</p>`}</div>`).join('')}</div>`);}
const sel=(key,options)=>`<select data-setting="${key}">${options.map(([v,k])=>`<option value="${v}" ${save.settings[key]===v?'selected':''}>${t(k)}</option>`).join('')}</select>`;
const slider=(key,min,max,step)=>`<input aria-label="${key}" data-setting="${key}" type="range" min="${min}" max="${max}" step="${step}" value="${save.settings[key]}">`;
function settings(){const rows=[['Language',sel('language',[['en','English'],['ru','Русский'],['lt','Lietuvių']])],['Controls',sel('controls',[['joystick','Joystick'],['arrows','Arrow pad']])],['Control size',slider('controlSize',90,200,5)],['Control opacity',slider('controlOpacity',.2,1,.05)],['Control side',sel('controlSide',[['left','Left'],['right','Right']])],['Bottom offset',slider('controlBottom',12,180,4)],['Music volume',slider('music',0,1,.05)],['Sound effects',slider('sfx',0,1,.05)],['Graphics quality',sel('quality',[['low','Low'],['medium','Medium'],['high','High']])],['Pixel sharpness',slider('sharpness',0,100,5)],['Effect pixel size',slider('pixelScale',1,3,1)],['Effect intensity',slider('fxIntensity',.25,1,.05)],['Screen shake',slider('screenShake',0,1,.05)],['Sound quality',sel('soundQuality',[['low','Low'],['high','High']])]];show('settings','Settings',`${rows.map(([name,control])=>`<div class="select-row"><label>${t(name)}</label>${control}</div>`).join('')}<p class="control-help">${t(save.settings.controls==='joystick'?'Touch anywhere in the arena to place the joystick. Release to hide it.':'Arrow-pad placement uses the side and bottom settings.')}</p><div class="row" style="margin-top:22px"><button data-action="playmusic">♫ ${t(save.settings.musicMuted?'Play music':'Mute music')}</button><button data-action="updates">${t('Check for updates')}</button><button data-action="export">${t('Export save')}</button><button data-action="import">${t('Import save')}</button></div><p style="margin-top:18px"><small>${t('Progress is backed up automatically, including before updates.')}<br>${t('Export a backup before changing devices or clearing browser data.')}</small></p>${playing&&run?damageStats():''}`);}
function damageStats(){const log=run.damageLog||{weapons:{},ritual:0,powerups:0,from:run.time},ids=[...new Set([...run.weapons.map(w=>w.id),...Object.keys(log.weapons)])],rows=ids.map(id=>({label:weapon(id).name,damage:log.weapons[id]||0}));rows.push({label:t('Ritual')+' · '+t(RITUALS[run.characterId||'rasa'].name),damage:log.ritual},{label:t('Power-ups'),damage:log.powerups});const total=rows.reduce((n,row)=>n+row.damage,0);return `<section class="damage-stats"><h3>${t('Damage this journey')}</h3><p class="muted">${t('Actual enemy damage, including burning. Tracking starts with this update.')}</p>${rows.sort((a,b)=>b.damage-a.damage).map(row=>`<div class="damage-row"><span>${row.label}</span><b>${Math.round(row.damage).toLocaleString(save.settings.language)}</b><div class="meter"><i style="width:${total?row.damage/total*100:0}%"></i></div></div>`).join('')}<p>${t('Total')}: <b>${Math.round(total).toLocaleString(save.settings.language)}</b></p></section>`;}
function releaseHistory(){return `<div class="release-notes">${CHANGELOG.filter(n=>n.build<=VERSION.build).sort((a,b)=>b.build-a.build).map((n,i)=>`${i===1?`<h3 class="history-heading">${t('Previous updates')}</h3>`:''}<section class="release-entry" data-build="${n.build}"><div class="row between"><h3>${t(n.title)}</h3><span class="badge">V${n.version}</span></div><ul>${n.items.map(item=>`<li>${t(item)}</li>`).join('')}</ul></section>`).join('')}</div>`;}
function whatsNew(){show('whatsnew',"What's new",`<div class="eyebrow">WISPBOUND · V${VERSION.name}${VERSION.test?' TEST':''}</div><p>${t('Your progress is kept. Here is what changed.')}</p>${releaseHistory()}<div class="actionbar"><button class="primary" data-action="close">${t('Got it')}</button></div>`);}

function upgradePreview(w){const before=weaponStats(run,w),after=weaponStats(run,{...w,level:w.level+1}),rows=[];for(const [key,label,format] of [['count',unitName(before.kind),x=>x],['damage','Damage',x=>x.toFixed(1)],['interval','Cooldown',x=>(x/COMBAT_SPEED).toFixed(2)+'s'],['range','Reach',x=>Math.round(x)],['pierce','Piercing',x=>x],['duration','Effect duration',x=>(x/COMBAT_SPEED).toFixed(2)+'s'],['radius','Size',x=>x.toFixed(1)],['speed','Projectile speed',x=>Math.round(x*COMBAT_SPEED)],['orbitSpeed','Orbit speed',x=>x.toFixed(2)],['burn','Burn damage',x=>x],['shards','Fragments',x=>x],['slow','Slow',x=>Math.round(x*100)+'%'],['angle','Fan width',x=>Math.round(x*180/Math.PI)+'°'],['flightTime','Flight time',x=>(x/COMBAT_SPEED).toFixed(2)+'s'],['delay','Warning time',x=>(x/COMBAT_SPEED).toFixed(2)+'s'],['armDelay','Seal delay',x=>(x/COMBAT_SPEED).toFixed(2)+'s'],['shock','Stun duration',x=>(x/COMBAT_SPEED).toFixed(2)+'s'],['knock','Knockback',x=>Math.round(x)]])if(Number.isFinite(after[key])&&after[key]!==before[key])rows.push([label,format(before[key]||0),format(after[key])]);return `<p class="upgrade-name">${t(upgradeName(w.id,w.level+1))}</p><div class="upgrade-stats">${rows.map(([label,a,b])=>`<div><span>${t(label)}</span><span><del>${a}</del> → <b>${b}</b></span></div>`).join('')}${after.cleave&&!before.cleave?`<div>${t('Threads cut every enemy they cross.')}</div>`:''}</div>${w.level===6?`<small class="gold">${t('Weapon mastered. Max a matching artifact, then collect an elite chest.')}</small>`:''}`;}


function updatesPanel(){const messages={idle:'Check for updates',checking:'Checking…',current:'You are up to date.',available:'An update is available.',downloading:'Downloading…',verifying:'Downloading…',ready:'Update ready. Your progress will be kept.',saveFailed:'Update paused: progress could not be saved. Export a backup and try again.',failed:'Update check failed. Try again when online.',active:'Finish the journey before installing an update.',installing:'Confirm installation in the Android window.',permission:'Allow WISPBOUND to install updates in Android settings, then return.',cancelled:'Installation cancelled. You can retry.'};const scroll=screen==='updates'?panel.scrollTop:0;show('updates','Updates',`<p>${t('Current version')}: <b class="gold">V${VERSION.name}${VERSION.test?' TEST':''}</b></p><div class="update-status" role="status">${t(messages[updater.state]||messages.failed)} ${Number.isFinite(updater.progress)&&updater.progress>=0?`${updater.progress}%`:''}</div>${run&&(!run.over||run.awaitingRevive)?`<p>${t('Finish the journey before installing an update.')}</p>`:''}<div class="row"><button data-action="check" ${['checking','downloading','verifying','installing'].includes(updater.state)?'disabled':''}>${t('Check for updates')}</button>${updater.state==='available'?`<button class="primary" data-action="download" ${run&&(!run.over||run.awaitingRevive)?'disabled':''}>${t('Download update')}</button>`:''}${['ready','cancelled'].includes(updater.state)?`<button class="primary" data-action="apply" ${run&&(!run.over||run.awaitingRevive)?'disabled':''}>${t('Restart & update')}</button>`:''}</div><h3 class="update-history-heading">${t('Update history')}</h3>${releaseHistory()}`);panel.scrollTop=scroll;}
function install(){show('install','Install & download',`<div class="row"><img class="download-qr" src="download-qr.svg" alt="QR code to open the WISPBOUND download page"><div class="stack"><a href="wispbound-android.apk" download>↓ ${t('Android APK')} · V${VERSION.name}${VERSION.test?' TEST':''}</a><p style="max-width:400px">${t('On iPhone: open this page in Safari, use Share, then Add to Home Screen.')}</p></div></div><p style="margin-top:24px">${t('No account required. Progress is saved on this device.')}</p><p>${t(updater.offlineReady?'Offline ready':updater.offlineFailed?'Offline setup unavailable in this browser.':'Preparing offline play…')}</p><small>${t('A native iPhone app will come with a later store release.')}</small>`);}
function privacy(){show('privacy','Privacy',`<p>${t('This build has no accounts, ads, purchases or gameplay analytics. Hosting and update requests may be recorded by the hosting provider. Saves remain on your device unless you export them.')}</p><p>${t('Export a backup before changing devices or clearing browser data.')}</p><p><small>WISPBOUND concept art. Four original retro scores, with original melodies, arrangements and sound effects. Prototype combat art is drawn in code. Version V${VERSION.name}${VERSION.test?' TEST':''}, 13 October 2026.</small></p>`);}
function controls(){releasePointer();const el=$('controls'),s=save.settings;el.classList.toggle('floating',s.controls==='joystick');el.style.width=el.style.height=s.controlSize+'px';el.style.opacity=s.controlOpacity;el.style.top='auto';el.style.bottom=`max(${s.controlBottom}px, env(safe-area-inset-bottom))`;el.style.left=s.controlSide==='left'?'24px':'auto';el.style.right=s.controlSide==='right'?'24px':'auto';$('run-actions').style.right=s.controlSide==='left'?'20px':'auto';$('run-actions').style.left=s.controlSide==='right'?'20px':'auto';el.innerHTML=s.controls==='joystick'?'<div class="joystick"><div class="stick"></div></div>':'<div class="dpad"><button data-dir="up" aria-label="Up">↑</button><button data-dir="left" aria-label="Left">←</button><button data-dir="right" aria-label="Right">→</button><button data-dir="down" aria-label="Down">↓</button></div>';}
const movement=bindMovementInput({arena:$('game'),controls:$('controls'),getMode:()=>save.settings.controls,isActive:()=>playing&&!paused&&!run?.over&&!panel.open,onInput:(value,id)=>{input=value;pointer=id;}});
function releasePointer(){movement.reset();}
window.addEventListener('resize',releasePointer);

function begin(){if(loadError){notice('Existing save could not be read. It has been kept unchanged.');return;}if(run&&(!run.over||run.awaitingRevive)){continueRun();return;}run=newCharacterRun(selectedMap,save.selectedCharacter,save);persist();continueRun();}
function continueRun(){if(!run)return;if(run.awaitingRevive){playing=true;result();return;}if(run.over)return;atGate=false;$('gate').hidden=true;playing=true;paused=false;panel.close();screen='';$('home').hidden=true;$('game').hidden=false;nativeRun();controls();$('minimap-tools').innerHTML=`<button data-action="settings" aria-label="${t('Settings')}" title="${t('Settings')}">⚙</button>`;$('run-actions').innerHTML=`<button data-action="rituals">◎ ${t('Evolutions')}</button><button data-action="pause">Ⅱ ${t('Pause')}</button>`;unlockAudio();syncAudio();updateHud();if(run.chestReward)chestPanel();else if(run.levelPending)levelPanel();else toast('Walk a loop to seal a ritual');}
function updateHud(){if(!run)return;$('hud').innerHTML=`<div class="hud-level" aria-label="${t('Level')} ${run.level}"><small>LV</small><b>${run.level}</b><div class="meter xp"><i style="width:${Math.min(100,run.xp/run.nextXp*100)}%"></i></div></div><div class="hud-time" aria-label="${t('Time survived')}">${fmt(run.time)}${run.freezeTime>0?`<small>${t('Time Stop')} ${Math.ceil(run.freezeTime)}s</small>`:''}</div><div class="hud-gold"><small>${t('Gold')}</small><b>${Math.floor(earnedGold(run)).toLocaleString('en')}</b></div>`;updateInventory();}

let inventorySignature='';
function updateInventory(){const signature=JSON.stringify([run.weapons.map(w=>[w.id,w.level,w.rank,w.resonance]),run.artifacts,save.settings.language]);if(signature===inventorySignature)return;inventorySignature=signature;
 const weaponCells=run.weapons.flatMap(w=>{const d=weapon(w.id),label=d.name+' · '+RANKS[w.rank]+' · '+(d.stage==='base'?'Lv.'+w.level:d.stage);const cell=`<div class="weapon-slot rank-slot-${w.rank}" style="--rank-color:${RANK_COLORS[w.rank]}" title="${label}" aria-label="${label}">${weaponIcon(w.id,'',w.rank??save.ranks[w.id]??0)}<small>${d.stage==='base'?w.level:'✦'}</small></div>`;return d.capacity===2?[cell,`<div class="weapon-slot fusion-slot" title="${t('Ultimate: two slots')}">${weaponIcon(w.id,'',w.rank??save.ranks[w.id]??0)}<small>↔</small></div>`]:[cell];});
 const artifactCells=Object.entries(run.artifacts).map(([id,l])=>`<div class="weapon-slot artifact-slot" title="${artifact(id).name} · ${t(artifact(id).label)} ${artifactValue(id,l)} · ${l}/6" aria-label="${artifact(id).name} · ${t(artifact(id).label)} ${artifactValue(id,l)} · ${l}/6">${artifactIcon(id)}<small>${l}</small></div>`);
 const group=(label,cells)=>`<section class="inventory-group" aria-label="${t(label)}"><div class="inventory-label">${t(label)} <span>${cells.length}/6</span></div><div class="inventory-slots">${cells.join('')}${Array.from({length:6-cells.length},()=>`<div class="weapon-slot empty-slot" aria-label="${t('Empty slot')}"><span>—</span></div>`).join('')}</div></section>`;
 const html=group('Weapons',weaponCells)+group('Artifacts',artifactCells);if($('inventory').innerHTML!==html)$('inventory').innerHTML=html;
}
function pause(){if(!playing)return;persist();show('pause','Paused',`<p>${t('Your journey is saved. You can continue from camp.')}</p><div class="stack"><button class="primary" data-action="close">${t('Resume')}</button><button data-action="settings">${t('Settings')}</button><button data-action="camp">${t('Return to camp')}</button><button data-action="end">${t('End journey')}</button></div>`);}
function levelPanel(){if(!run.choices.length)makeChoices(run,save);sound('level');show('level','Choose a gift',`<div class="eyebrow">${t('Level up')} · ${run.level}</div><div class="cards choices">${run.choices.map((c,i)=>{const d=c.type==='artifact'?artifact(c.id):weapon(c.id),badge=knownBadge(save,run,c.id);return `<button class="card choice" data-choice="${i}">${weapon(c.id)?weaponIcon(c.id,'',run.weapons.find(w=>w.id===c.id)?.rank??save.ranks[c.id]??0):c.type==='artifact'?artifactIcon(c.id):`<span class="symbol">${c.type==='heal'?'♥':'✦'}</span>`}<h3>${d?.name||t(c.type==='heal'?'Restore health':'Take gold')}</h3>${weapon(c.id)?rankBadge(c.type==='upgrade'?run.weapons.find(w=>w.id===c.id).rank:(save.ranks[c.id]||0)):''}<small>${c.type==='upgrade'?`${t('Weapon level')} ${run.weapons.find(w=>w.id===c.id).level+1}/7`:c.type==='weapon'?t('New weapon'):c.type==='artifact'?`${t('Artifact')} ${(run.artifacts[c.id]||0)+1}/6`:''}</small><small>${t(d?.description||d?.theme||'')}</small>${c.type==='upgrade'?upgradePreview(run.weapons.find(w=>w.id===c.id)):c.type==='artifact'?`<div class="upgrade-stats"><div><span>${t(d.label)}</span><span><del>${artifactValue(c.id,run.artifacts[c.id]||0)}</del> → <b>${artifactValue(c.id,(run.artifacts[c.id]||0)+1)}</b></span></div></div>`:''}${badge?`<span class="badge">✦ ${t(badge[0].toUpperCase()+badge.slice(1))}</span>`:''}</button>`;}).join('')}</div>${run.rerolls>0?`<div class="actionbar"><button data-action="reroll">${t('Reroll gifts')} · ${run.rerolls}</button></div>`:''}`,false);persist();}
function ritualPanel(){show('rituals','Evolutions',`<p class="panel-note">${t('Master a weapon to level 7 and a matching artifact to level 6. Collect a guardian or boss chest for one 70% evolution chance.')}</p><p>${t('An evolution replaces one reward. Otherwise the chest still gives upgrades. Recipes appear after your first discovery.')}</p><div class="section-label">${t('Ultimate rituals')}</div><p>${t('After 15 minutes, two matching evolved weapons and a catalyst can fuse through an elite chest. An Ultimate uses one slot.')}</p><div class="section-label">${t('Discovered')}</div>${save.discovered.length?save.discovered.map(id=>{const recipe=RECIPES.find(x=>x.id===id)||ULTIMATES.find(x=>x.id===id);return `<div class="recipe-line">${weaponIcon(id,'inline-art')}${weapon(id).name}: ${recipe.baseId?weapon(recipe.baseId).name+' Lv.7 + '+artifact(recipe.artifactId).name+' Lv.6':recipe.components.map(id=>weapon(id).name).join(' + ')} · ${t('Elite chest')}</div>`;}).join(''):`<p>${t('Perform an evolution to reveal its recipe here.')}</p>`}`);}

function evolutionResult(id){persist();sound('evolve');const d=weapon(id);renderer.celebrate('evolve',d.color);panel.style.setProperty('--ritual-color',d.color);show('evolution','Ritual discovered',`<div class="evolution-result"><div class="ritual-halo" aria-hidden="true"></div>${weaponIcon(d.id,'evolution-weapon')}<h2 class="gold">${d.name}</h2><p>${t(d.description)}</p><button class="primary" data-action="close">${t('Resume')}</button></div>`);updateHud();}
let chestRevealTimer;
function revealChest(){if(!run?.chestReward)return;run.chestReward.revealed=true;persist(true);const grid=panel.querySelector('.chest-rewards');grid?.classList.add('revealed');const button=panel.querySelector('[data-action="revealchest"]');if(button){button.dataset.action='ackchest';button.textContent=t(run.chestReward.final?'The light endures':'Continue journey')+' ↗';}sound(run.chestReward.rewards.some(g=>g.type==='evolution')?'evolve':'level');}
function chestPanel(){const chest=run.chestReward;if(!chest)return;clearTimeout(chestRevealTimer);persist(true);const spectacular=chest.rewards.some(g=>g.type==='evolution'),icon=g=>g.type==='artifact'?artifactIcon(g.id):g.type==='supplies'?'<span class="supply-medal">✦</span>':weaponIcon(g.id),reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
 show('chest',spectacular?'A new power awakens':'Spoils of the Guardian',`<p class="chest-subtitle">${t('Rewards')}: ${chest.rewards.length} · ${t('Your rewards are saved.')}</p><div class="chest-rewards ${chest.revealed||reduced?'revealed':''} ${spectacular?'evolution-reveal':''}" style="--reward-count:${chest.rewards.length}">${chest.rewards.map((g,i)=>`<article class="card chest-reward ${g.type==='evolution'?'evolution-card':''}" style="--reveal:${i*.18}s"><span class="eyebrow">0${i+1}</span><div class="reward-reel" aria-hidden="true"><div class="reward-strip">${Array.from({length:8},(_,j)=>`<div>${j%2?artifactIcon(ARTIFACTS[(i+j)%ARTIFACTS.length].id):weaponIcon(BASES[(i+j)%BASES.length].id)}</div>`).join('')}<div>${icon(g)}</div></div></div><div class="reward-label"><h3>${g.type==='supplies'?t('Mastery supplies'):g.type==='artifact'?artifact(g.id).name:weapon(g.id).name}</h3><p>${g.type==='evolution'?t(weapon(g.id).stage==='ultimate'?'ULTIMATE EVOLUTION':'EVOLUTION DISCOVERED'):g.type==='supplies'?`+${g.gold} ${t('Gold')} · +${g.shards} ${t('Shards')} · +${g.health} ${t('Health')}`:g.type==='resonance'?`${t('Resonance')} ${g.from} → ${g.to}<br>+4% ${t('damage')}`:g.type==='artifact'?`${t('Level')} ${g.from} → ${g.to}<br>${t(artifact(g.id).label)} ${artifactValue(g.id,g.to)}`:`${t('Weapon level')} ${g.from} → ${g.to}<br>${t(upgradeName(g.id,g.to))}`}</p></div></article>`).join('')}</div>${chest.bonus?`<p class="gold">${t('Royal Treasury')} · +150 ${t('Gold')} · +1 ${t('Shards')}</p>`:''}<button class="primary chest-continue" data-action="${chest.revealed||reduced?'ackchest':'revealchest'}">${t(chest.revealed||reduced?chest.final?'The light endures':'Continue journey':'Skip reveal')} ↗</button>`,false);
 updateHud();if(!chest.revealed&&!reduced)chestRevealTimer=setTimeout(()=>{if(run?.chestReward?.id===chest.id&&screen==='chest')revealChest();},2600+(chest.rewards.length-1)*180);
}

function revivePanel(){persist(true);nativeRun();const cost=reviveCost(run);show('fallen','One more light',`<p>${t('Revive with 50% health and 3 seconds of protection.')}</p><p>${t('Revives used')}: ${run.paidRevives||0} / 2</p><p>${t('Gold')}: ${Math.floor(reviveWallet(run,save))}</p><div class="actionbar"><button class="primary" data-action="paidrevive" ${reviveWallet(run,save)<cost?'disabled':''}>${t('Revive')} · ${cost} ${t('Gold')}</button><button data-action="acceptdeath">${t('End journey')}</button></div><p class="muted">${t('First revive: 500 gold. Second: 1000 gold. The next death ends the journey.')}</p>`,false);}
function purchaseRevive(){const previousRun=structuredClone(run),previousSave=structuredClone(save);if(!buyRevive(run,save))return;if(!persist(true)){run=previousRun;save=previousSave;revivePanel();return;}sound('evolve');continueRun();}
function result(){if(run.awaitingRevive){revivePanel();return;}claimRun(run,save);persist();nativeRun();show('result',run.won?'The light endures':'The light returns',`<div class="cards"><div class="card"><div class="result-num">${fmt(run.time)}</div><small>${t('Time survived')}</small></div><div class="card"><div class="result-num">${run.kills}</div><small>${t('Spirits released')}</small></div><div class="card"><div class="result-num">${earnedGold(run)}</div><small>${t('Gold')} · ${run.shards} ${t('Shards')}</small></div><div class="card"><div class="result-num">${save.heroLevel}</div><small>${t('Hero level')} · ${Math.floor(save.heroXp)}/${heroXpForLevel(save.heroLevel)} XP</small></div></div><div class="actionbar"><button class="primary" data-action="finish">${t('Back to camp')}</button></div>`,false);}
function exportSave(){const data=saves.export(save,run);if(!data){notice('Progress could not be saved. Export a backup.');return;}if(globalThis.WispboundNative){WispboundNative.exportSave(data);return;}const blob=new Blob([data],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='wispbound-save.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notice('Save exported');}
async function importSave(){const f=document.createElement('input');f.type='file';f.accept='.json,application/json';f.hidden=true;document.body.append(f);f.addEventListener('cancel',()=>f.remove(),{once:true});f.onchange=async()=>{try{if(!f.files[0]||f.files[0].size>5e6)throw Error();const data=decodeSave(await f.files[0].text());const imported=profileBook.create(save,run,data);save=imported.profile;run=imported.run;loadError=false;home();notice('Save imported');}catch{notice('Invalid save file. Existing progress was kept.');}finally{f.remove();}};f.click();}
document.addEventListener('change',e=>{const k=e.target.dataset.setting;if(!k)return;save.settings[k]=e.target.type==='range'?Number(e.target.value):e.target.value;persist();controls();syncAudio();if(k==='controls')settings();if(k==='language'){document.documentElement.lang=save.settings.language;settings();if(!playing){const was=screen;home();screen=was;settings();}}});
document.addEventListener('click',e=>{const el=e.target.closest('button');if(!el||el.disabled)return;unlockAudio();const d=el.dataset;if(d.slot){if(!persist(true))return;try{activateProfile(profileBook.load(d.slot,save,run));}catch{notice('Progress could not be saved. Export a backup.');}return;}if(d.branch){selectedBranch=d.branch;selectedSkill='';skills();return;}if(d.node){skillPopup(d.node);return;}if(d.map){selectedMap=d.map;journey();return;}if(d.forge){if(forge(save,d.forge)){sound('evolve');persist();arsenal();panel.querySelector(`[data-forge="${d.forge}"]`)?.closest('.card').classList.add('just-unlocked');}return;}if(d.skill){if(profileAction(s=>learnSkill(s,d.skill))){sound('evolve');const scroll=panel.scrollTop;skills();panel.scrollTop=scroll;skillPopup(d.skill);}return;}if(d.buycharacter){if(profileAction(s=>buyCharacter(s,d.buycharacter))){sound('evolve');characters();}return;}if(d.character){if(profileAction(s=>selectCharacter(s,d.character)))characters();return;}if(d.achievement){if(profileAction(s=>claimAchievement(s,d.achievement))){sound('level');const scroll=panel.scrollTop;achievements();panel.scrollTop=scroll;}return;}if(d.choice!==undefined){const choice=run.choices[Number(d.choice)];if(takeChoice(run,save,Number(d.choice))){if(choice.type==='upgrade'){renderer.celebrate('upgrade',weapon(choice.id).color);toast('Weapon upgraded');}if(run.levelPending)levelPanel();else{screen='';closePanel();persist();updateHud();}}return;}
 const actions={paidrevive:purchaseRevive,acceptdeath:()=>{if(finishDeath(run))result();},newprofile:newProfile,loadprofiles:loadProfiles,revealchest:revealChest,playmusic:toggleMusic,ackchest:()=>{if(acknowledgeChest(run)){persist();panel.close();screen='';if(run.over)result();else if(run.chestReward)chestPanel();else if(run.levelPending)levelPanel();else{paused=false;syncAudio();}}},characters,achievements,closeskill:()=>$('skill-popup').close(),claimall:()=>{if(profileAction(s=>{const ids=readyAchievements(s).map(a=>a.id);for(const id of ids)claimAchievement(s,id);return ids.length>0;})){sound('level');achievements();}},title:titleScreen,entercamp:enterCamp,reroll:()=>{if(rerollChoices(run,save))levelPanel();},whatsnew:()=>whatsNew(),journey,start:begin,continue:continueRun,arsenal,skills,codex,settings,install,privacy,close:closePanel,pause,rituals:ritualPanel,camp:()=>{persist();home();},end:()=>{if(run&&(!run.over||run.awaitingRevive)){run.awaitingRevive=false;run.over=true;result();}},finish:()=>{run=null;persist();home();},respec:()=>{if(profileAction(s=>{s.skills=[];s.refundedSkills=0;return true;}))skills();},updates:()=>{updatesPanel();updater.check();},check:()=>updater.check(),download:()=>updater.download(),apply:()=>updater.apply(),export:exportSave,import:importSave};actions[d.action]?.();});
document.addEventListener('keydown',e=>{if(!playing)return;if(e.key==='Escape'){if(!panel.open)pause();return;}if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','w','a','s','d','W','A','S','D'].includes(e.key)){if(panel.open)return;e.preventDefault();keys.add(e.key.toLowerCase());}});document.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));
document.addEventListener('visibilitychange',()=>{if(document.hidden){keys.clear();releasePointer();if(playing&&!paused)pause();persist();music.pause();}else syncAudio();});window.addEventListener('blur',()=>{keys.clear();releasePointer();});window.addEventListener('pagehide',persist);
globalThis.onNativePause=()=>{nativeBackground=true;keys.clear();releasePointer();if(playing&&!paused)pause();persist();syncAudio();};globalThis.onNativeResume=()=>{nativeBackground=false;syncAudio();};
function frame(now){music.tick(now);const dt=Math.min(.05,(now-last)/1000||0);last=now;if(playing&&run){if(!paused&&!run.over){let move=pointer!==null?input:{x:(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('a')||keys.has('arrowleft')?1:0),y:(keys.has('s')||keys.has('arrowdown')?1:0)-(keys.has('w')||keys.has('arrowup')?1:0)};const viewScale=Math.max(.65,Math.min(1.2,Math.min(innerWidth,innerHeight)/660));run.viewHalfWidth=innerWidth/viewScale/2;run.viewHalfHeight=innerHeight/viewScale/2;const beforeTime=run.time,events=step(run,move,dt);save.playedSeconds=(save.playedSeconds||0)+Math.max(0,run.time-beforeTime);if(events.includes('kill'))killSound();if(events.includes('revive')){sound('evolve');renderer.celebrate('evolve','#f4c97d');toast('Phoenix Ember · Revived');}if(events.includes('second_wind'))toast('Second Wind');if(events.includes('boss')){renderer.celebrate('boss','#dd876e');sound('boss');}if(events.includes('upgrade')){const u=run.lastUpgrade;sound('level');renderer.celebrate('upgrade','#ffe3a0');toast(u?.id?`${t('Instant Upgrade')} · ${(u.type==='weapon'?weapon(u.id):artifact(u.id)).name} ${u.from} → ${u.to}`:'All equipment mastered · +75 Gold · +25 Health');persist();}for(const [id,label] of [['time_stop','Time Stop'],['magnet','Magnet'],['fireblast','Fireblast'],['xp','Journey XP'],['bread','Bread · +30 HP']])if(events.includes(id)){sound('ritual');toast(label);}if(events.includes('boss_clear')){renderer.celebrate('victory','#f0c276');}if(events.includes('ritual')||events.includes('ritual_echo')){sound('ritual');renderer.celebrate('ritual',RITUALS[run.characterId||'rasa'].color);toast(RITUALS[run.characterId||'rasa'].name);}if(events.includes('hurt'))renderer.celebrate('hurt','#b74c57');if(run.over)result();else if(run.chestReward)chestPanel();else if(run.levelPending)levelPanel();saveClock+=dt;if(saveClock>10){saveClock=0;persist();}}renderer.draw(run,save.settings.quality,save.settings.language,save.settings);hudClock+=dt;if(hudClock>.15){hudClock=0;updateHud();syncAudio();}}requestAnimationFrame(frame);}
titleScreen();if(loaded.status==='recovered')notice('Progress recovered from an automatic backup.');if(loadError)notice('Existing save could not be read. It has been kept unchanged.');if(location.hash==='#download'){home();install();}requestAnimationFrame(frame);

